    private static class StoredRuleEntries {
        private static final Object INDEX_FILE = new Object();

        private final Path folder;
        private final Map<String, String> fileNamesByRule;
        private final Map<String, Optional<Path>> filesByRule = new HashMap<>();
        private final Set<String> sharedRules = new HashSet<>();

        StoredRuleEntries(Path folder, Path indexFile, Map<String, String> fileNamesByRule) {
            this.folder = folder;
            this.fileNamesByRule = fileNamesByRule;

            // Keys are file names, normalized paths and identities of regular files. Keys of different kinds are only ever
            // equal if they denote the same file. The index file itself is a reference as well, so it can never be deleted.
            SetMultimap<Object, Object> referencesByTarget = HashMultimap.create();
            FileIdentities fileIdentities = new FileIdentities();
            addTargets(referencesByTarget, INDEX_FILE, Optional.of(indexFile.toAbsolutePath()), fileIdentities);
            fileNamesByRule.forEach((rule, fileName) -> {
                Optional<Path> file = resolve(fileName);
                filesByRule.put(rule, file);
                referencesByTarget.put(fileName, rule);
                addTargets(referencesByTarget, rule, file, fileIdentities);
            });

            for (Collection<Object> references : referencesByTarget.asMap().values()) {
                if (references.size() > 1) {
                    references.stream().filter(String.class::isInstance).map(String.class::cast).forEach(sharedRules::add);
                }
            }
