        private static void addTargets(SetMultimap<Object, Object> referencesByTarget, Object reference, Optional<Path> file, FileIdentities fileIdentities) {
            file.ifPresent(path -> {
                referencesByTarget.put(path.normalize(), reference);
                fileIdentities.of(path).ifPresent(identity -> referencesByTarget.put(identity, reference));
            });
        }

        private Optional<Path> resolve(String fileName) {
