    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        // keeps the index and the rule files consistent with a concurrent repair of the same store
        synchronized (storedRules) {
            if (integrity == Integrity.REPAIR && violations.isEmpty()) {
                forget(rule);
                return;
            }
            String ruleFileName = ensureRuleFileName(rule);
            write(violations, ruleFileName);
        }
    }

    private void forget(ArchRule rule) {
        String ruleDescription = rule.getDescription();
        if (!storedRules.containsKey(ruleDescription)) {
            log.trace("Rule '{}' without violations is not stored, nothing to save", ruleDescription);
            return;
        }

        String storedRule = ensureUnixLineBreaks(ruleDescription);
        StoredRuleEntries entries = analyzeStoredRules();
        if (entries.isShared(storedRule)) {
            log.trace("Forgetting rule '{}', leaving file {} shared with other rules", ruleDescription, entries.getFileName(storedRule));
        } else if (entries.isBroken(storedRule)) {
            log.trace("Forgetting rule '{}' with broken entry pointing to {}", ruleDescription, entries.getFileName(storedRule));
        } else {
            Path ruleFile = entries.getFile(storedRule).get();
            try {
                deleteRuleFile(ruleFile);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(String.format("Cannot delete file %s of rule '%s'", ruleFile, ruleDescription), e);
            }
            log.trace("Forgetting rule '{}' together with its file {}", ruleDescription, ruleFile);
        }
        storedRules.remove(singleton(storedRule));
    }

    private void write(List<String> violations, String ruleFileName) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        try {
            Files.write(resolveRuleFile(ruleFileName), builder.toString().getBytes(UTF_8));
        } catch (IOException | InvalidPathException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private Path resolveRuleFile(String ruleFileName) {
        return storeFolder.toPath().resolve(ruleFileName);
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    private String ensureRuleFileName(ArchRule rule) {
        String ruleDescription = rule.getDescription();
        String candidateFileName = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
        String existingFileName = storedRules.putIfAbsent(ruleDescription, candidateFileName);
        if (existingFileName == null) {
            log.trace("Assigning new file {} to rule '{}'", candidateFileName, ruleDescription);
            return candidateFileName;
        }
        log.trace("Rule '{}' is already stored in file {}", ruleDescription, existingFileName);
        return existingFileName;
    }
